/* See HostText.h. */

#include "HostText.h"

#include <cmath>
#include <cstdio>
#include <unordered_map>

#define STB_TRUETYPE_IMPLEMENTATION
#include "../third_party/stb/stb_truetype.h"

#include "BrainoFontTtf.h"   // generated by cmake/EmbedFont.cmake

namespace HostText {
namespace {

stbtt_fontinfo font;
bool tried = false;
bool ok = false;
int capUnits = 0;   // the height of 'H' in font units: what capPx is measured against

bool ready() {
    if (tried) return ok;
    tried = true;
    const int at = stbtt_GetFontOffsetForIndex(BRAINO_FONT_TTF, 0);
    ok = at >= 0 && stbtt_InitFont(&font, BRAINO_FONT_TTF, at) != 0;
    if (ok) {
        int x0 = 0, y0 = 0, x1 = 0, y1 = 0;
        ok = stbtt_GetCodepointBox(&font, 'H', &x0, &y0, &x1, &y1) != 0 && y1 > 0;
        capUnits = y1;
    }
    std::printf("[text] host: %s\n", ok ? "FreeSans, anti-aliased at the panel's resolution"
                                        : "font did not load; drawing the bitmap fonts");
    return ok;
}

std::unordered_map<uint64_t, Glyph> cache;
std::unordered_map<uint64_t, bool> missing;

}   // namespace

const Glyph* glyph(int capPx, uint32_t code) {
    if (capPx <= 0 || !ready()) return nullptr;
    const uint64_t key = (static_cast<uint64_t>(capPx) << 32) | code;
    const auto hit = cache.find(key);
    if (hit != cache.end()) return &hit->second;
    if (missing.count(key)) return nullptr;
    if (code != ' ' && stbtt_FindGlyphIndex(&font, static_cast<int>(code)) == 0) {
        missing[key] = true;
        return nullptr;
    }

    const float scale = static_cast<float>(capPx) / static_cast<float>(capUnits);
    Glyph g;
    int adv = 0, lsb = 0;
    stbtt_GetCodepointHMetrics(&font, static_cast<int>(code), &adv, &lsb);
    g.advance = static_cast<int16_t>(std::lround(adv * scale));
    int x0 = 0, y0 = 0, x1 = 0, y1 = 0;
    stbtt_GetCodepointBitmapBox(&font, static_cast<int>(code), scale, scale, &x0, &y0, &x1, &y1);
    if (x1 > x0 && y1 > y0) {
        g.w = static_cast<int16_t>(x1 - x0);
        g.h = static_cast<int16_t>(y1 - y0);
        g.xoff = static_cast<int16_t>(x0);
        g.yoff = static_cast<int16_t>(y0);
        g.alpha.assign(static_cast<size_t>(g.w) * g.h, 0);
        stbtt_MakeCodepointBitmap(&font, g.alpha.data(), g.w, g.h, g.w, scale, scale,
                                  static_cast<int>(code));
    }
    return &(cache[key] = std::move(g));
}

}   // namespace HostText
